package com.pousadamarealta;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.pousadamarealta.db.Database;
import com.pousadamarealta.repository.MessageRepository;
import com.pousadamarealta.repository.ReservationRepository;
import com.pousadamarealta.repository.RoomRepository;
import com.pousadamarealta.service.NotificationService;
import com.pousadamarealta.service.PricingService;
import com.pousadamarealta.service.ReportService;
import com.pousadamarealta.service.ReservationService;
import com.pousadamarealta.web.ApiController;
import io.javalin.Javalin;
import kong.unirest.core.HttpResponse;
import kong.unirest.core.Unirest;
import org.junit.jupiter.api.*;

import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class IntegrationTest {
    private Javalin app;
    private String baseUrl;
    private ObjectMapper objectMapper;

    @BeforeAll
    void setup() {
        String dbUrl = "jdbc:h2:mem:test;MODE=PostgreSQL;DATABASE_TO_LOWER=TRUE;DEFAULT_NULL_ORDERING=HIGH";
        String dbUser = "sa";
        String dbPassword = "";

        Database database = new Database(dbUrl, dbUser, dbPassword);
        database.initialize();

        RoomRepository roomRepository = new RoomRepository(database);
        ReservationRepository reservationRepository = new ReservationRepository(database);
        MessageRepository messageRepository = new MessageRepository(database);

        PricingService pricingService = new PricingService();
        NotificationService notificationService = new NotificationService(messageRepository);
        ReservationService reservationService = new ReservationService(
                reservationRepository, roomRepository, pricingService, notificationService);
        ReportService reportService = new ReportService(reservationRepository, roomRepository);

        ApiController apiController = new ApiController(
                roomRepository, reservationService, messageRepository, reportService);

        app = Javalin.create(config -> {
            config.http.defaultContentType = "application/json";
        });

        apiController.registerRoutes(app);
        app.start(0);

        baseUrl = "http://localhost:" + app.port();
        objectMapper = new ObjectMapper();
        objectMapper.registerModule(new JavaTimeModule());
    }

    @AfterAll
    void teardown() {
        if (app != null) {
            app.stop();
        }
    }

    @Test
    void testGetRooms() {
        HttpResponse<String> response = Unirest.get(baseUrl + "/rooms").asString();
        assertEquals(200, response.getStatus());

        List<Map> rooms = parseJson(response.getBody(), List.class);
        assertEquals(5, rooms.size());

        Map<String, Object> room101 = rooms.get(0);
        assertEquals("101", room101.get("number"));
        assertEquals("STANDARD", room101.get("type"));
        assertEquals(2, room101.get("capacity"));
        assertEquals(249.90, ((Number) room101.get("nightlyRate")).doubleValue(), 0.01);
    }

    @Test
    void testCreateAndConfirmReservation() {
        Map<String, Object> request = Map.of(
                "roomNumber", "101",
                "guestName", "João Silva",
                "guestEmail", "joao@example.com",
                "guestCpf", "12345678901",
                "checkIn", "2027-03-10",
                "checkOut", "2027-03-12",
                "guests", 2,
                "ratePlan", "STANDARD"
        );

        HttpResponse<String> createResponse = Unirest.post(baseUrl + "/reservations")
                .header("Content-Type", "application/json")
                .body(request)
                .asString();

        assertEquals(201, createResponse.getStatus());
        Map<String, Object> reservation = parseJson(createResponse.getBody(), Map.class);

        assertEquals(1L, ((Number) reservation.get("id")).longValue());
        assertEquals("PENDING", reservation.get("status"));
        assertEquals(2, reservation.get("nights"));
        assertEquals(0.0, ((Number) reservation.get("amountPaid")).doubleValue(), 0.01);

        Long id = ((Number) reservation.get("id")).longValue();
        HttpResponse<String> confirmResponse = Unirest.post(baseUrl + "/reservations/" + id + "/confirmation")
                .asString();

        assertEquals(200, confirmResponse.getStatus());
        Map<String, Object> confirmed = parseJson(confirmResponse.getBody(), Map.class);
        assertEquals("CONFIRMED", confirmed.get("status"));
        assertEquals(((Number) confirmed.get("total")).doubleValue(),
                ((Number) confirmed.get("amountPaid")).doubleValue(), 0.01);
    }

    @Test
    void testHighSeasonPricing() {
        Map<String, Object> request = Map.of(
                "roomNumber", "101",
                "guestName", "Maria Santos",
                "guestEmail", "maria@example.com",
                "guestCpf", "98765432109",
                "checkIn", "2027-07-10",
                "checkOut", "2027-07-12",
                "guests", 1,
                "ratePlan", "STANDARD"
        );

        HttpResponse<String> response = Unirest.post(baseUrl + "/reservations")
                .header("Content-Type", "application/json")
                .body(request)
                .asString();

        assertEquals(201, response.getStatus());
        Map<String, Object> reservation = parseJson(response.getBody(), Map.class);

        assertEquals(599.76, ((Number) reservation.get("subtotal")).doubleValue(), 0.01);
        assertEquals(599.76, ((Number) reservation.get("total")).doubleValue(), 0.01);
    }

    @Test
    void testNonRefundableDiscount() {
        Map<String, Object> request = Map.of(
                "roomNumber", "201",
                "guestName", "Ana Costa",
                "guestEmail", "ana@example.com",
                "guestCpf", "11122233344",
                "checkIn", "2027-03-10",
                "checkOut", "2027-03-12",
                "guests", 2,
                "ratePlan", "NON_REFUNDABLE"
        );

        HttpResponse<String> response = Unirest.post(baseUrl + "/reservations")
                .header("Content-Type", "application/json")
                .body(request)
                .asString();

        assertEquals(201, response.getStatus());
        Map<String, Object> reservation = parseJson(response.getBody(), Map.class);

        assertEquals(779.80, ((Number) reservation.get("subtotal")).doubleValue(), 0.01);
        assertEquals(116.97, ((Number) reservation.get("discount")).doubleValue(), 0.01);
        assertEquals(662.83, ((Number) reservation.get("total")).doubleValue(), 0.01);
    }

    @Test
    void testRoomConflict() {
        Map<String, Object> request1 = Map.of(
                "roomNumber", "102",
                "guestName", "Pedro Lima",
                "guestEmail", "pedro@example.com",
                "guestCpf", "55566677788",
                "checkIn", "2027-04-10",
                "checkOut", "2027-04-15",
                "guests", 2,
                "ratePlan", "STANDARD"
        );

        HttpResponse<String> response1 = Unirest.post(baseUrl + "/reservations")
                .header("Content-Type", "application/json")
                .body(request1)
                .asString();
        assertEquals(201, response1.getStatus());

        Map<String, Object> request2 = Map.of(
                "roomNumber", "102",
                "guestName", "Carlos Souza",
                "guestEmail", "carlos@example.com",
                "guestCpf", "99988877766",
                "checkIn", "2027-04-12",
                "checkOut", "2027-04-17",
                "guests", 1,
                "ratePlan", "STANDARD"
        );

        HttpResponse<String> response2 = Unirest.post(baseUrl + "/reservations")
                .header("Content-Type", "application/json")
                .body(request2)
                .asString();

        assertEquals(409, response2.getStatus());
        Map<String, Object> error = parseJson(response2.getBody(), Map.class);
        assertEquals("ROOM_UNAVAILABLE", error.get("error"));
    }

    @Test
    void testCapacityExceeded() {
        Map<String, Object> request = Map.of(
                "roomNumber", "101",
                "guestName", "Família Grande",
                "guestEmail", "familia@example.com",
                "guestCpf", "44455566677",
                "checkIn", "2027-05-01",
                "checkOut", "2027-05-05",
                "guests", 3,
                "ratePlan", "STANDARD"
        );

        HttpResponse<String> response = Unirest.post(baseUrl + "/reservations")
                .header("Content-Type", "application/json")
                .body(request)
                .asString();

        assertEquals(422, response.getStatus());
        Map<String, Object> error = parseJson(response.getBody(), Map.class);
        assertEquals("CAPACITY_EXCEEDED", error.get("error"));
    }

    @Test
    void testCheckInCheckOut() {
        Map<String, Object> request = Map.of(
                "roomNumber", "202",
                "guestName", "Laura Mendes",
                "guestEmail", "laura@example.com",
                "guestCpf", "33344455566",
                "checkIn", "2027-06-01",
                "checkOut", "2027-06-03",
                "guests", 2,
                "ratePlan", "STANDARD"
        );

        HttpResponse<String> createResponse = Unirest.post(baseUrl + "/reservations")
                .header("Content-Type", "application/json")
                .body(request)
                .asString();
        Long id = ((Number) parseJson(createResponse.getBody(), Map.class).get("id")).longValue();

        Unirest.post(baseUrl + "/reservations/" + id + "/confirmation").asString();

        HttpResponse<String> checkInResponse = Unirest.post(baseUrl + "/reservations/" + id + "/check-in")
                .asString();
        assertEquals(200, checkInResponse.getStatus());
        assertEquals("CHECKED_IN", parseJson(checkInResponse.getBody(), Map.class).get("status"));

        HttpResponse<String> checkOutResponse = Unirest.post(baseUrl + "/reservations/" + id + "/check-out")
                .asString();
        assertEquals(200, checkOutResponse.getStatus());
        Map<String, Object> receipt = parseJson(checkOutResponse.getBody(), Map.class);
        assertEquals("Comprovante de reserva", receipt.get("title"));
        assertEquals(id, ((Number) receipt.get("reservationId")).longValue());
    }

    @Test
    void testCancellationWithRefund() {
        Map<String, Object> request = Map.of(
                "roomNumber", "301",
                "guestName", "Roberto Alves",
                "guestEmail", "roberto@example.com",
                "guestCpf", "22233344455",
                "checkIn", "2027-08-01",
                "checkOut", "2027-08-05",
                "guests", 3,
                "ratePlan", "STANDARD"
        );

        HttpResponse<String> createResponse = Unirest.post(baseUrl + "/reservations")
                .header("Content-Type", "application/json")
                .body(request)
                .asString();
        Long id = ((Number) parseJson(createResponse.getBody(), Map.class).get("id")).longValue();

        Unirest.post(baseUrl + "/reservations/" + id + "/confirmation").asString();

        HttpResponse<String> cancelResponse = Unirest.post(baseUrl + "/reservations/" + id + "/cancellation")
                .asString();
        assertEquals(200, cancelResponse.getStatus());
        Map<String, Object> cancelled = parseJson(cancelResponse.getBody(), Map.class);
        assertEquals("CANCELLED", cancelled.get("status"));
        assertEquals(((Number) cancelled.get("amountPaid")).doubleValue(),
                ((Number) cancelled.get("refund")).doubleValue(), 0.01);
    }

    @Test
    void testCancellationNonRefundable() {
        Map<String, Object> request = Map.of(
                "roomNumber", "201",
                "guestName", "Beatriz Fernandes",
                "guestEmail", "beatriz@example.com",
                "guestCpf", "77788899900",
                "checkIn", "2027-09-01",
                "checkOut", "2027-09-03",
                "guests", 2,
                "ratePlan", "NON_REFUNDABLE"
        );

