                "checkOut", "2027-12-01",
                "guests", 1,
                "ratePlan", "STANDARD"
        );

        HttpResponse<String> response = Unirest.post(baseUrl + "/reservations")
                .header("Content-Type", "application/json")
                .body(request)
                .asString();

        assertEquals(400, response.getStatus());
        Map<String, Object> error = parseJson(response.getBody(), Map.class);
        assertEquals("INVALID_REQUEST", error.get("error"));
    }

    @Test
    void testReservationNotFound() {
        HttpResponse<String> response = Unirest.get(baseUrl + "/reservations/999999").asString();
        assertEquals(404, response.getStatus());
        Map<String, Object> error = parseJson(response.getBody(), Map.class);
        assertEquals("RESERVATION_NOT_FOUND", error.get("error"));
    }

    @Test
    void testRoomNotFound() {
        Map<String, Object> request = Map.of(
                "roomNumber", "999",
                "guestName", "Teste",
                "guestEmail", "teste@example.com",
                "guestCpf", "12345678901",
                "checkIn", "2027-12-01",
                "checkOut", "2027-12-02",
                "guests", 1,
                "ratePlan", "STANDARD"
        );

        HttpResponse<String> response = Unirest.post(baseUrl + "/reservations")
                .header("Content-Type", "application/json")
                .body(request)
                .asString();

        assertEquals(404, response.getStatus());
        Map<String, Object> error = parseJson(response.getBody(), Map.class);
        assertEquals("ROOM_NOT_FOUND", error.get("error"));
    }

    private <T> T parseJson(String json, Class<T> clazz) {
        try {
            return objectMapper.readValue(json, clazz);
        } catch (Exception e) {
            throw new RuntimeException("Failed to parse JSON", e);
        }
    }
}

