        assertTrue(plansResponse.body().contains("Pousada Maré Alta,rate-plans,2027-03"));
        assertTrue(plansResponse.body().contains("STANDARD,"));
        assertTrue(plansResponse.body().contains("NON_REFUNDABLE,"));
    }
}

