package com.pousadamarealta.db;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.sql.Statement;

public class Database {
    private final String url;
    private final String user;
    private final String password;

    public Database(String url, String user, String password) {
        this.url = url;
        this.user = user;
        this.password = password;
    }

    public Connection getConnection() throws SQLException {
        return DriverManager.getConnection(url, user, password);
    }

    public void initialize() {
        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement()) {

            boolean isH2 = conn.getMetaData().getDatabaseProductName().equals("H2");

            stmt.execute("""
                CREATE TABLE IF NOT EXISTS rooms (
                    number VARCHAR(10) PRIMARY KEY,
                    type VARCHAR(20) NOT NULL
                )
                """);

            if (isH2) {
                stmt.execute("""
                    CREATE TABLE IF NOT EXISTS reservations (
                        id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                        room_number VARCHAR(10) NOT NULL,
                        guest_name VARCHAR(255) NOT NULL,
                        guest_email VARCHAR(255) NOT NULL,
                        guest_cpf VARCHAR(20) NOT NULL,
                        check_in DATE NOT NULL,
                        check_out DATE NOT NULL,
                        guests INTEGER NOT NULL,
                        rate_plan VARCHAR(20) NOT NULL,
                        nights INTEGER NOT NULL,
                        subtotal DECIMAL(10, 2) NOT NULL,
                        discount DECIMAL(10, 2) NOT NULL,
                        total DECIMAL(10, 2) NOT NULL,
                        status VARCHAR(20) NOT NULL,
                        amount_paid DECIMAL(10, 2) NOT NULL DEFAULT 0,
                        refund DECIMAL(10, 2),
                        FOREIGN KEY (room_number) REFERENCES rooms(number)
                    )
                    """);

                stmt.execute("""
                    CREATE TABLE IF NOT EXISTS messages (
                        id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                        channel VARCHAR(20) NOT NULL,
                        recipient VARCHAR(255) NOT NULL,
                        subject VARCHAR(500) NOT NULL,
                        body TEXT NOT NULL
                    )
                    """);
            } else {
                stmt.execute("""
                    CREATE TABLE IF NOT EXISTS reservations (
                        id BIGSERIAL PRIMARY KEY,
                        room_number VARCHAR(10) NOT NULL,
                        guest_name VARCHAR(255) NOT NULL,
                        guest_email VARCHAR(255) NOT NULL,
                        guest_cpf VARCHAR(20) NOT NULL,
                        check_in DATE NOT NULL,
                        check_out DATE NOT NULL,
                        guests INTEGER NOT NULL,
                        rate_plan VARCHAR(20) NOT NULL,
                        nights INTEGER NOT NULL,
                        subtotal DECIMAL(10, 2) NOT NULL,
                        discount DECIMAL(10, 2) NOT NULL,
                        total DECIMAL(10, 2) NOT NULL,
                        status VARCHAR(20) NOT NULL,
                        amount_paid DECIMAL(10, 2) NOT NULL DEFAULT 0,
                        refund DECIMAL(10, 2),
                        FOREIGN KEY (room_number) REFERENCES rooms(number)
                    )
                    """);

                stmt.execute("""
                    CREATE TABLE IF NOT EXISTS messages (
                        id BIGSERIAL PRIMARY KEY,
                        channel VARCHAR(20) NOT NULL,
                        recipient VARCHAR(255) NOT NULL,
                        subject VARCHAR(500) NOT NULL,
                        body TEXT NOT NULL
                    )
                    """);
            }

            long roomCount = 0;
            try (var rs = stmt.executeQuery("SELECT COUNT(*) FROM rooms")) {
                if (rs.next()) {
                    roomCount = rs.getLong(1);
                }
            }

            if (roomCount == 0) {
                stmt.execute("INSERT INTO rooms (number, type) VALUES ('101', 'STANDARD')");
                stmt.execute("INSERT INTO rooms (number, type) VALUES ('102', 'STANDARD')");
                stmt.execute("INSERT INTO rooms (number, type) VALUES ('201', 'DELUXE')");
                stmt.execute("INSERT INTO rooms (number, type) VALUES ('202', 'DELUXE')");
                stmt.execute("INSERT INTO rooms (number, type) VALUES ('301', 'SUITE')");
            }

            conn.commit();

        } catch (SQLException e) {
            throw new RuntimeException("Failed to initialize database", e);
        }
    }
}

